-- GENERATED by scripts/build-pipeline-sql.sh from databricks/sql/{00,01,01b,02,03,05}*.sql. Do not edit by hand.
-- Target: workspace.ux_telemetry, Volume raw_events. Run all statements in order; every step is safe to re-run.

-- ===================================================================== 00_setup.sql
-- Run once. Replace workspace / ux_telemetry / raw_events with your workspace values
-- (Free Edition: use your own catalog, NOT `system`; e.g. catalog=workspace, schema=ux_telemetry, volume=raw_events).
-- Spark/Databricks SQL (not run by the local test harness).
CREATE SCHEMA IF NOT EXISTS workspace.ux_telemetry COMMENT 'UX telemetry research pipeline (bronze/silver/gold)';
CREATE VOLUME IF NOT EXISTS workspace.ux_telemetry.raw_events COMMENT 'Landing zone for raw JSONL telemetry from the uxtelemetry SDK / extension';
-- Upload JSONL files to: /Volumes/workspace/ux_telemetry/raw_events/raw/

-- ===================================================================== 01_bronze_ddl.sql
-- BRONZE: raw events exactly as the SDK sends them (one row per event), plus load metadata. No cleaning here.
-- Explicit schema so downstream SQL never breaks when a field is absent from a given batch.
-- Portable subset: also executed by the local SQLite test harness (STRING -> TEXT there).
CREATE TABLE IF NOT EXISTS workspace.ux_telemetry.bronze_events (
  t BIGINT, recv_t BIGINT,
  sid STRING, st STRING, app STRING, task STRING, tcat STRING, pid STRING,
  page STRING, path STRING, type STRING, tab BIGINT, frame BIGINT,
  x DOUBLE, y DOUBLE, v DOUBLE, btn BIGINT,
  tag STRING, role STRING, uxid STRING, testid STRING, label STRING, region STRING, dom STRING, action STRING,
  interactive BOOLEAN, ptr BOOLEAN, n BIGINT,
  how STRING, chars BIGINT, words BIGINT, hash STRING, text STRING,
  ctx STRING, combo STRING, del BIGINT,
  dur DOUBLE, pos DOUBLE, ratio DOUBLE, state STRING,
  status STRING, satisfaction BIGINT, answer STRING, name STRING,
  chart STRING, series STRING, prompt STRING,
  w BIGINT, h BIGINT, dpr DOUBLE,
  _source_file STRING, _ingested_at TIMESTAMP
);

-- ===================================================================== 01b_bronze_load.sql
-- Load raw JSONL from the Volume into bronze, skipping files that are already loaded (by _source_file).
-- Spark/Databricks SQL only. UNTESTED in this form: replaces COPY INTO, whose column list failed on files that
-- lack optional fields (UNRESOLVED_COLUMN `tab`: app-recorded events have no tab/frame, only the extension sends them).
-- read_files with an EXPLICIT schema fixes both known COPY INTO problems:
--   * a field absent from a file comes back as NULL instead of a missing column
--   * whole numbers are parsed straight into the DOUBLE columns, so no BIGINT vs DOUBLE merge conflict
-- Re-running is safe: files whose path is already in bronze_events are not loaded again.
INSERT INTO workspace.ux_telemetry.bronze_events
SELECT t, recv_t, sid, st, app, task, tcat, pid, page, path, type, tab, frame, x, y, v, btn, tag, role, uxid, testid, label, region, dom, action, interactive, ptr, n, how, chars, words, hash, text, ctx, combo, del, dur, pos, ratio, state, status, satisfaction, answer, name, chart, series, prompt, w, h, dpr,
       _metadata.file_path AS _source_file, current_timestamp() AS _ingested_at
FROM read_files(
  '/Volumes/workspace/ux_telemetry/raw_events/raw/',
  format => 'json',
  schema => 't BIGINT, recv_t BIGINT, sid STRING, st STRING, app STRING, task STRING, tcat STRING, pid STRING, page STRING, path STRING, type STRING, tab BIGINT, frame BIGINT, x DOUBLE, y DOUBLE, v DOUBLE, btn BIGINT, tag STRING, role STRING, uxid STRING, testid STRING, label STRING, region STRING, dom STRING, action STRING, interactive BOOLEAN, ptr BOOLEAN, n BIGINT, how STRING, chars BIGINT, words BIGINT, hash STRING, text STRING, ctx STRING, combo STRING, del BIGINT, dur DOUBLE, pos DOUBLE, ratio DOUBLE, state STRING, status STRING, satisfaction BIGINT, answer STRING, name STRING, chart STRING, series STRING, prompt STRING, w BIGINT, h BIGINT, dpr DOUBLE'
)
WHERE _metadata.file_path NOT IN (
  SELECT DISTINCT _source_file FROM workspace.ux_telemetry.bronze_events WHERE _source_file IS NOT NULL
);

-- ===================================================================== 02_silver.sql
-- SILVER: typed, de-duplicated, human-readable names; trials reconstructed from task_start/outcome events.
-- Portable subset (runs in Databricks SQL and in the local SQLite harness). Keep comments free of semicolons.

-- Events may be re-sent (keepalive retries), so keep one row per (session, time, type, element, position).
CREATE OR REPLACE TABLE workspace.ux_telemetry.silver_events AS
SELECT session_id, session_type, app_id, app_version, participant_id, task_id, task_category, page, path, event_type,
       ts_ms, uxid, testid, label, region, action, tag, role, interactive, ptr, x, y, v, n, dur,
       status, satisfaction, answer, chart, series, prompt_text, how, chars, words, prompt_hash, ctx, combo, name
FROM (
  SELECT sid AS session_id, st AS session_type, app AS app_id, substr(app, -2) AS app_version, pid AS participant_id,
         task AS task_id, tcat AS task_category, page, path, type AS event_type,
         CAST(t AS BIGINT) AS ts_ms, uxid, testid, label, region, action, tag, role, interactive, ptr, x, y, v, n, dur,
         status, satisfaction, answer, chart, series, text AS prompt_text, how, chars, words, hash AS prompt_hash, ctx, combo, name,
         ROW_NUMBER() OVER (
           PARTITION BY sid, t, type, COALESCE(uxid, ''), COALESCE(x, -1), COALESCE(y, -1)
           ORDER BY recv_t
         ) AS rn
  FROM workspace.ux_telemetry.bronze_events
  WHERE sid IS NOT NULL AND t IS NOT NULL
) d
WHERE rn = 1;

-- One row per (session, task) trial. Assumes each task is attempted once per session.
-- outcome: correct | incorrect | abandoned | no_outcome (the participant left without finishing)
CREATE OR REPLACE TABLE workspace.ux_telemetry.silver_trials AS
SELECT s.session_id, s.session_type, s.app_id, s.app_version, s.participant_id, s.task_id, s.task_category,
       s.start_ms,
       o.end_ms,
       COALESCE(o.outcome, 'no_outcome') AS outcome,
       o.satisfaction,
       o.answer,
       o.duration_ms
FROM (
  SELECT session_id, task_id, task_category, app_id, app_version, participant_id, session_type, MIN(ts_ms) AS start_ms
  FROM workspace.ux_telemetry.silver_events
  WHERE event_type = 'task_start'
  GROUP BY session_id, task_id, task_category, app_id, app_version, participant_id, session_type
) s
LEFT JOIN (
  SELECT session_id, task_id, MAX(ts_ms) AS end_ms, MAX(status) AS outcome,
         MAX(satisfaction) AS satisfaction, MAX(answer) AS answer, MAX(dur) AS duration_ms
  FROM workspace.ux_telemetry.silver_events
  WHERE event_type = 'outcome'
  GROUP BY session_id, task_id
) o ON o.session_id = s.session_id AND o.task_id = s.task_id;

-- ===================================================================== 03_gold.sql
-- GOLD: research metrics. Each metric is a hypothesis about a construct, motivated by the HCI literature triage
-- (docs/literature/signal_paper_matrix.csv). The paper links are title-level and UNVERIFIED until the matrix is filled in.
--   rage / dead clicks      -> frustration or "looks clickable" affordance errors     (struggle/frustration detection papers)
--   hover dwell, hovers     -> attention / reading effort on chart marks              (cursor-as-attention: Huang et al. 2012)
--   idle_ms, first action   -> hesitation / confusion before acting                   (implicit behavioral measures: Rzeszotarski & Kittur 2011)
--   outcome + satisfaction  -> objective success vs self-report; "satisfied but wrong" = over-trust (Human-AI reliance work)
-- Portable subset (Databricks SQL and the local SQLite harness). Study-panel clicks are excluded from friction counts.

-- Per-trial friction metrics: behavior events that fall inside the trial's time window.
CREATE OR REPLACE TABLE workspace.ux_telemetry.gold_trial_metrics AS
SELECT t.session_id, t.session_type, t.app_id, t.app_version, t.participant_id, t.task_id, t.task_category,
       t.outcome, t.satisfaction, t.duration_ms,
       SUM(CASE WHEN e.event_type = 'click' THEN 1 ELSE 0 END) AS n_clicks,
       SUM(CASE WHEN e.event_type = 'rage_click' THEN 1 ELSE 0 END) AS n_rage_clicks,
       SUM(CASE WHEN e.event_type = 'click' AND e.ptr = TRUE AND e.interactive = FALSE THEN 1 ELSE 0 END) AS n_dead_clicks,
       SUM(CASE WHEN e.event_type = 'chart_hover' THEN 1 ELSE 0 END) AS n_chart_hovers,
       COALESCE(SUM(CASE WHEN e.event_type = 'chart_hover' THEN e.dur END), 0) AS chart_hover_ms,
       SUM(CASE WHEN e.event_type = 'chart_legend_click' THEN 1 ELSE 0 END) AS n_legend_clicks,
       COALESCE(SUM(CASE WHEN e.event_type = 'idle_end' THEN e.dur END), 0) AS idle_ms,
       SUM(CASE WHEN e.event_type = 'prompt_submit' THEN 1 ELSE 0 END) AS n_prompts,
       MIN(CASE WHEN e.event_type IN ('click', 'key', 'chart_hover', 'chart_click') THEN e.ts_ms END) - t.start_ms AS first_action_ms
FROM workspace.ux_telemetry.silver_trials t
LEFT JOIN workspace.ux_telemetry.silver_events e
  ON e.session_id = t.session_id
 AND e.ts_ms >= t.start_ms
 AND e.ts_ms <= COALESCE(t.end_ms, 9223372036854775807)
 AND COALESCE(e.region, '') <> 'aside:study-panel'
GROUP BY t.session_id, t.session_type, t.app_id, t.app_version, t.participant_id, t.task_id, t.task_category,
         t.outcome, t.satisfaction, t.duration_ms, t.start_ms;

-- Per session type x task x design version: outcomes and friction. overtrust_rate = share of WRONG answers rated satisfied (4-5).
-- session_type is a grouping key so simulated (bot) trials are never averaged together with human ones.
CREATE OR REPLACE TABLE workspace.ux_telemetry.gold_task_summary AS
SELECT session_type, app_version, task_id, task_category,
       COUNT(*) AS n_trials,
       AVG(CASE WHEN outcome = 'correct' THEN 1.0 ELSE 0.0 END) AS success_rate,
       AVG(CASE WHEN outcome = 'abandoned' THEN 1.0 ELSE 0.0 END) AS abandon_rate,
       AVG(satisfaction) AS avg_satisfaction,
       AVG(duration_ms) AS avg_duration_ms,
       AVG(n_rage_clicks) AS avg_rage_clicks,
       AVG(n_dead_clicks) AS avg_dead_clicks,
       AVG(n_chart_hovers) AS avg_chart_hovers,
       AVG(n_legend_clicks) AS avg_legend_clicks,
       AVG(idle_ms) AS avg_idle_ms,
       AVG(first_action_ms) AS avg_first_action_ms,
       SUM(CASE WHEN outcome = 'incorrect' AND satisfaction >= 4 THEN 1.0 ELSE 0.0 END)
         / NULLIF(SUM(CASE WHEN outcome = 'incorrect' THEN 1.0 ELSE 0.0 END), 0) AS overtrust_rate
FROM workspace.ux_telemetry.gold_trial_metrics
GROUP BY session_type, app_version, task_id, task_category;

-- Which UI elements attract rage / dead clicks (excludes the study panel). Ranks candidate affordance problems.
CREATE OR REPLACE TABLE workspace.ux_telemetry.gold_element_friction AS
SELECT session_type, app_version, uxid,
       SUM(CASE WHEN event_type = 'click' THEN 1 ELSE 0 END) AS n_clicks,
       SUM(CASE WHEN event_type = 'rage_click' THEN 1 ELSE 0 END) AS n_rage_clicks,
       SUM(CASE WHEN event_type = 'click' AND ptr = TRUE AND interactive = FALSE THEN 1 ELSE 0 END) AS n_dead_clicks,
       COUNT(DISTINCT session_id) AS n_sessions,
       SUM(CASE WHEN event_type = 'rage_click' THEN 1.0 ELSE 0.0 END)
         / NULLIF(SUM(CASE WHEN event_type = 'click' THEN 1.0 ELSE 0.0 END), 0) AS rage_per_click
FROM workspace.ux_telemetry.silver_events
WHERE uxid IS NOT NULL AND event_type IN ('click', 'rage_click') AND COALESCE(region, '') <> 'aside:study-panel'
GROUP BY session_type, app_version, uxid;

-- Before/after for the iteration loop: v1 (current UI) vs v2 (proposed change), per session type and task.
CREATE OR REPLACE TABLE workspace.ux_telemetry.gold_version_comparison AS
SELECT a.session_type, a.task_id, a.task_category,
       a.success_rate AS success_rate_v1, b.success_rate AS success_rate_v2, b.success_rate - a.success_rate AS success_delta,
       a.abandon_rate AS abandon_rate_v1, b.abandon_rate AS abandon_rate_v2,
       a.avg_duration_ms AS avg_duration_ms_v1, b.avg_duration_ms AS avg_duration_ms_v2,
       a.avg_rage_clicks AS avg_rage_clicks_v1, b.avg_rage_clicks AS avg_rage_clicks_v2,
       a.overtrust_rate AS overtrust_rate_v1, b.overtrust_rate AS overtrust_rate_v2,
       a.n_trials AS n_trials_v1, b.n_trials AS n_trials_v2
FROM workspace.ux_telemetry.gold_task_summary a
JOIN workspace.ux_telemetry.gold_task_summary b ON a.task_id = b.task_id AND a.session_type = b.session_type
WHERE a.app_version = 'v1' AND b.app_version = 'v2';

-- ===================================================================== 05_comments.sql
-- Unity Catalog comments carry the research context to Genie (and to anyone browsing the catalog).
-- Genie reads table/column descriptions, so definitions written here steer how it answers.
-- Spark/Databricks SQL only. UNTESTED (no workspace access from the sandbox).

COMMENT ON TABLE workspace.ux_telemetry.gold_trial_metrics IS
  'One row per (session, task) trial with friction metrics. Behavior counts exclude the study panel. Data with session_type=simulated is bot-generated test data, not real users.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_trial_metrics.outcome IS
  'Objective result: correct, incorrect, abandoned (clicked I give up), or no_outcome (left without finishing). Success = correct.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_trial_metrics.satisfaction IS
  'Self-reported 1-5 (5 = very satisfied) asked after answering. NULL when abandoned. Self-report, so compare with outcome rather than trusting it alone.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_trial_metrics.task_category IS
  'Amar, Eagan and Stasko (2005) low-level analytic task the trial exercises: retrieve_value, filter, compute_derived_value, find_extremum, sort, determine_range, characterize_distribution, find_anomalies, cluster, correlate.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_trial_metrics.n_rage_clicks IS
  'Bursts of 3+ clicks within 700 ms in the same spot. Proxy for frustration or a control that looks usable but does not respond.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_trial_metrics.n_dead_clicks IS
  'Clicks on non-interactive elements that show a pointer cursor ("looks clickable but is not"). Affordance problem signal.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_trial_metrics.idle_ms IS
  'Total time in pauses of 30 s or more with no input during the trial. Proxy for hesitation or confusion, not proof.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_trial_metrics.chart_hover_ms IS
  'Total time hovering chart marks. Cursor-as-attention proxy: cursor position only loosely tracks gaze.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_trial_metrics.first_action_ms IS
  'Milliseconds from trial start to the first click, key press, or chart interaction outside the study panel.';

COMMENT ON TABLE workspace.ux_telemetry.gold_task_summary IS
  'Aggregates of gold_trial_metrics per session_type (human or simulated, never mixed), design version (v1 = current UI, v2 = proposed change) and task. success_rate and abandon_rate are 0-1 fractions.';
COMMENT ON COLUMN workspace.ux_telemetry.gold_task_summary.overtrust_rate IS
  'Share of INCORRECT answers that were rated 4-5 for satisfaction ("satisfied but wrong"). NULL when no incorrect answers.';

COMMENT ON TABLE workspace.ux_telemetry.gold_element_friction IS
  'Rage and dead clicks per session_type, UI element (uxid) and design version. Highest rage_per_click flags elements with affordance problems.';

COMMENT ON TABLE workspace.ux_telemetry.gold_version_comparison IS
  'v1 vs v2 per session_type and task (human and simulated are separate rows): success_delta = success_rate_v2 - success_rate_v1. Used to judge whether a proposed UI change helped. Small samples: treat as descriptive.';
